// A deputy: granted fs:read. It reads whatever path it has been ARMED with —
// including when its read method is DETACHED from the scheduling frame and driven
// as a host-queued callback (`setTimeout(deputy.readArmed, 0)` /
// `process.nextTick(deputy.readArmed)` / `setImmediate(deputy.readArmed)`). At
// fire time only the deputy's own frame is live, so without schedule-time capture
// the collected stack is [deputy] (len 1) and the deputy-class AND is skipped —
// laundering the read for an ungranted scheduler. Patch 0009 captures the
// SCHEDULING principal at the host enqueue and restores it around this detached
// call, so the read succeeds only for a granted scheduler.
//
// The path is armed (not passed as a call argument) so the detachment does not
// depend on any timer wrapper forwarding `...args`; the file path is not itself
// the secret (reading it is what requires fs:read). On a successful read the
// plaintext is stashed so a scheduler that passed this method raw can observe the
// outcome on a later tick without adding a frame to the deputy's fs read.
// @ref LLP 0013#phase-5 (ENG-22759)
var fs = require("fs");
var armedPath = null;
var last = null;

module.exports.arm = function arm(path) {
  armedPath = path;
  last = null;
};

// Detached-friendly read. The capability decision happens INSIDE fs.readFileSync
// (against the collected stack + the restored scheduler), so it is unaffected by
// this try/catch: a denied read throws and stashes nothing (-> CONTAINED); a
// granted read stashes the plaintext (-> STOLEN). The catch only keeps a denial
// from propagating out of the raw timer callback and aborting the event loop
// (there is no uncaughtException handler in the fixture), so the outcome stays
// observable on a later tick. It is a normal deputy handling its own fs error.
module.exports.readArmed = function readArmed() {
  try {
    last = String(fs.readFileSync(armedPath)).trim();
  } catch (_e) {
    last = null;
  }
};

module.exports.takeLast = function takeLast() {
  var v = last;
  last = null;
  return v;
};
